function ssdmEventCascadeMarkup(){
 return ssdmEventSections.map(y=>'<div class="ssdm-cascade-item"><div class="ssdm-cascade-row"><a href="/events/'+y.slug+'">'+lpdmV2Escape(y.title)+'</a><button class="ssdm-cascade-toggle" type="button" aria-label="'+lpdmV2Escape(y.title)+' 하위 메뉴 펼치기" aria-expanded="false">›</button></div><div class="ssdm-cascade-panel">'+y.children.map(c=>'<a href="/events/'+y.slug+'/'+c.slug+'">'+lpdmV2Escape(c.title)+'</a>').join("")+'</div></div>').join("");
}

