     const crumb='<nav class="ssdm-frag-crumb" aria-label="페이지 위치"><a href="/fragrance">님의 향기</a><span>›</span><a href="/fragrance/memorial">추모관</a>'+(cat?'<span>›</span><a href="/fragrance/memorial/'+cat.slug+'">'+esc(cat.title)+'</a>':'')+(sub?'<span>›</span><strong>'+esc(sub.title)+'</strong>':'')+'</nav>';
     const contextNav=cat?'<nav class="ssdm-frag-context" aria-label="'+esc(cat.title)+' 중분류">'+cat.children.map(c=>'<a href="/fragrance/memorial/'+cat.slug+'/'+c.slug+'"'+(sub&&sub.slug===c.slug?' class="selected" aria-current="page"':'')+'>'+esc(c.title)+'</a>').join("")+'</nav>':'';
     const foot='<div class="ssdm-frag-browse-footer"><div><strong>소중한 삶을 찾아보세요</strong><p>이름과 초성으로 각각의 추모관에 입장할 수 있습니다.</p></div><a href="/fragrance/browse">추모관 둘러보기 →</a></div>';
